const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Sakha Republic geometry (approximate bounding box)
  const sakha = ee.Geometry.Rectangle([105, 55, 165, 75]);

  // 2. Load burned area data for both years
  const burned2015 = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterDate('2015-01-01', '2015-12-31')
    .filterBounds(sakha)
    .select('BurnDate');

  const burned2021 = ee.ImageCollection('MODIS/006/MCD64A1')
    .filterDate('2021-01-01', '2021-12-31')
    .filterBounds(sakha)
    .select('BurnDate');

  // Check if collections are empty
  const size2015 = burned2015.size().getInfo();
  const size2021 = burned2021.size().getInfo();

  console.log(`2015 Images: ${size2015}, 2021 Images: ${size2021}`);

  if (size2015 === 0 || size2021 === 0) {
    console.log('Empty collection detected');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Create annual burned area masks (any pixel burned during the year)
  const burnMask2015 = burned2015.max().gt(0);
  const burnMask2021 = burned2021.max().gt(0);

  // 4. Calculate burned area (count of burned pixels * pixel area)
  // MODIS is 500m resolution = 0.25 km² per pixel
  const pixelArea = ee.Image.pixelArea().divide(1e6); // Convert to km²

  const burnedArea2015 = burnMask2015.multiply(pixelArea);
  const burnedArea2021 = burnMask2021.multiply(pixelArea);

  // 5. Sum total burned area for each year
  const area2015Result = burnedArea2015.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 3000,
    maxPixels: 1e9
  });

  const area2021Result = burnedArea2021.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sakha,
    scale: 3000,
    maxPixels: 1e9
  });

  // Count valid pixels
  const count2015Result = burnMask2015.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sakha,
    scale: 3000,
    maxPixels: 1e9
  });

  const count2021Result = burnMask2021.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: sakha,
    scale: 3000,
    maxPixels: 1e9
  });

  const area2015 = area2015Result.get('BurnDate').getInfo();
  const area2021 = area2021Result.get('BurnDate').getInfo();
  const count2015 = count2015Result.get('BurnDate').getInfo();
  const count2021 = count2021Result.get('BurnDate').getInfo();

  console.log(`2015 Burned Area: ${area2015 ? area2015.toFixed(2) : 'null'} km², Pixels: ${count2015 || 0}`);
  console.log(`2021 Burned Area: ${area2021 ? area2021.toFixed(2) : 'null'} km², Pixels: ${count2021 || 0}`);

  // 6. Validation and answer
  if (area2015 === null || area2021 === null || isNaN(area2015) || isNaN(area2021)) {
    console.log('Calculation returned invalid values');
    console.log('<answer>C3</answer>');
    return;
  }

  if (count2015 === 0 && count2021 === 0) {
    console.log('No valid pixels in either year');
    console.log('<answer>C2</answer>');
    return;
  }

  // Compare burned areas
  if (area2015 > area2021) {
    console.log('More forest burned in 2015 than 2021');
    console.log('<answer>A</answer>');
  } else {
    console.log('2021 had equal or more burned area than 2015');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
